  const _mp = r.macros || {};
  const _totCal = (_mp.p || 0) * 4 + (_mp.c || 0) * 4 + (_mp.f || 0) * 9 || 1;
  const pPct = Math.round(((_mp.p || 0) * 4 / _totCal) * 100);
