    const byDow = [null, null, null, null, null, null, null];
    const seq = [];
    for (const d of (days || [])) {
      if (Number.isInteger(d.dow) && d.dow >= 0 && d.dow <= 6 && !byDow[d.dow]) byDow[d.dow] = d;
      else seq.push(d);
    }
    for (let i = 0; i < 7 && seq.length; i++) if (!byDow[i]) byDow[i] = seq.shift();

