// Tier-colored ring + avatar; shows role, tier, and a Message CTA. (Read-only;
// respects privacy — only reachable when the post isn't marked private.)
// Member (client) profiles use the Terrain design; coaches use the Signal
// design; both are immersive living-identity pages (above).
function BSPublicProfile({ person, onBack, onMessage = () => {}, isSelf = false, onEdit = () => {}, meMode = false, onOpenSettings = () => {}, onOpenScore = () => {} }) {
  // Every profile you view (from chat, the feed, follows, search…) feeds the
  // search screen's "Recent" list — recently viewed, not just recently searched.
  React.useEffect(() => {
    if (isSelf || meMode || !person || !person.who) return;
    const role = person.kind === 'TRAINER' ? 'trainer' : person.kind === 'NUTRI' ? 'nutritionist' : 'client';
    bsRecentSearchPush({ userId: person.userId || null, name: person.who, role, avatar: person.photo || null, tier: person.tier || null, points: null });
  }, []);
  if (person.kind === 'TRAINER' || person.kind === 'NUTRI') {
    return <BSSignalCoachProfile person={person} onBack={onBack} onMessage={onMessage} isSelf={isSelf} onEdit={onEdit} meMode={meMode} onOpenSettings={onOpenSettings} onOpenScore={onOpenScore} />;
  }
  return <BSTerrainProfile person={person} onBack={onBack} onMessage={onMessage} isSelf={isSelf} onEdit={onEdit} meMode={meMode} onOpenSettings={onOpenSettings} onOpenScore={onOpenScore} />;
}

// ── Universal search — find anyone on Shape ──────────────────────────────────
// Opened from the ⌕ in every header (`shape:openSearch`). Live typeahead over
// every account (search_shape_people RPC — members + coaches, photo + tier),
// recent searches (localStorage), role filter chips, and the demo cast as the
// signed-out fallback. Tapping a person opens their living public profile.
const BS_RECENT_SEARCH_KEY = 'shape.recentSearch';
function bsRecentSearchRead() { try { const a = JSON.parse(localStorage.getItem(BS_RECENT_SEARCH_KEY) || '[]'); return Array.isArray(a) ? a : []; } catch (e) { return []; } }
function bsRecentSearchPush(p) {
  try {
    const a = bsRecentSearchRead().filter(x => (x.userId || x.name) !== (p.userId || p.name));
    a.unshift(p);
    localStorage.setItem(BS_RECENT_SEARCH_KEY, JSON.stringify(a.slice(0, 8)));
    try { window.dispatchEvent(new Event('shape:recentSearch')); } catch (e2) {}
  } catch (e) {}
}
// Inline row actions — follow / message someone straight from the results,
// without opening their profile first. Real accounts only (demo cast hides them).
function BSSearchFollowBtn({ uid, teal }) {
  const t = useBS();
  const cached = (typeof window !== 'undefined' && window.ShapeFollows?.getCached && window.ShapeFollows.getCached(uid)) || null;
  const [st, setSt] = React.useState(cached ? { following: !!cached.is_following, pending: !!cached.is_pending } : null);
  const [busy, setBusy] = React.useState(false);
  React.useEffect(() => {
    let dead = false;
    if (!st && window.ShapeFollows?.stats) window.ShapeFollows.stats(uid).then(s => { if (!dead && s) setSt({ following: !!s.is_following, pending: !!s.is_pending }); }).catch(() => {});
    return () => { dead = true; };
  }, [uid]);
  const on = !!(st && (st.following || st.pending));
  const label = st && st.following ? 'Following' : st && st.pending ? 'Requested' : 'Follow';
  return (
    <button disabled={busy} onClick={async () => { if (busy) return; setBusy(true); try { const r = await window.ShapeFollows.toggle(uid); if (r) setSt({ following: !!r.is_following, pending: !!r.is_pending }); } catch (e) {} setBusy(false); }}
      style={{ flexShrink: 0, padding: '6px 11px', borderRadius: 999, cursor: 'pointer', border: `1px solid ${on ? t.RULE : teal}`, background: on ? 'transparent' : (t.isLight ? `${teal}14` : `${teal}22`), color: on ? t.INK50 : teal, fontFamily: t.MONO, fontSize: 8.5, fontWeight: 800, letterSpacing: '0.1em', textTransform: 'uppercase', opacity: busy ? 0.6 : 1 }}>{label}</button>
  );
}
function BSSearchMsgBtn({ uid, name }) {
  const t = useBS();
  const [busy, setBusy] = React.useState(false);
  return (
    <button disabled={busy} aria-label={`Message ${name}`} onClick={async () => {
      if (busy) return; setBusy(true);
      try {
        const r = await window.ShapeMessages.getOrCreateMemberConversation({ otherUserId: uid });
        const cid = (r && r.data) || null;
        if (cid) { try { window.dispatchEvent(new CustomEvent('shape:openConversation', { detail: { conversationId: cid, name } })); } catch (e) {} }
      } catch (e2) { try { window.__bsToast && window.__bsToast('Could not open the conversation — try again.', 'error'); } catch (e3) {} }
      setBusy(false);
    }}
      style={{ width: 30, height: 30, flexShrink: 0, borderRadius: 999, border: `1px solid ${t.RULE}`, background: 'transparent', color: t.INK, cursor: 'pointer', display: 'grid', placeItems: 'center', padding: 0, opacity: busy ? 0.6 : 1 }}>
      <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><path d="M21 11.5a8.38 8.38 0 0 1-9 8.4 8.5 8.5 0 0 1-3.4-.7L3 21l1.8-5.6a8.38 8.38 0 0 1-.8-3.9 8.5 8.5 0 0 1 8.5-8.5 8.38 8.38 0 0 1 8.5 8.5Z" /></svg>
    </button>
  );
}

function BSUniversalSearch({ onClose }) {
  const t = useBS();
  const teal = t.isLight ? '#0a8f87' : '#34d6c5';
  const [q, setQ] = useStateBSC('');
  const [filter, setFilter] = useStateBSC('all'); // all | members | coaches
  const [rows, setRows] = useStateBSC(null);
  const [busy, setBusy] = useStateBSC(false);
  const [recents, setRecents] = useStateBSC(bsRecentSearchRead);
  const [suggested, setSuggested] = useStateBSC([]);
  const [viewPerson, setViewPerson] = useStateBSC(null);
  const inputRef = React.useRef(null);
  React.useEffect(() => { const id = setTimeout(() => { try { inputRef.current && inputRef.current.focus(); } catch (e) {} }, 80); return () => clearTimeout(id); }, []);

  const signedIn = !!(typeof window !== 'undefined' && window.ShapeAuth?.getCachedState?.()?.user?.id);
  const demoPeople = React.useMemo(() => [
    { name: 'Jordan Chen', role: 'trainer' }, { name: 'Dr. Maya Patel', role: 'nutritionist' },
    ...BS_FOLLOW_DEMO_NAMES.map(n => ({ name: n, role: 'client' })),
  ].map(p => ({ ...p, userId: null, avatar: bsDemoFace(p.name), points: null, demo: true })), []);

  // Suggested people for the empty state — "people you may know" from the
  // follow graph first (get_follow_suggestions: mutuals + follows-you ranked),
  // then any accounts on Shape, then the demo cast when signed out.
  const [suggestKind, setSuggestKind] = useStateBSC('on'); // 'know' | 'on'
  React.useEffect(() => {
    let dead = false;
    (async () => {
      if (signedIn && window.ShapeFollows?.suggestions) {
        try {
          const sug = await window.ShapeFollows.suggestions(8);
          if (!dead && Array.isArray(sug) && sug.length) {
            let avatars = {};
            try { avatars = (await window.ShapeProfiles.getUserAvatars(sug.map(s => s.userId))) || {}; } catch (e) {}
            if (!dead) { setSuggested(sug.map(s => ({ ...s, avatar: avatars[s.userId] || null, points: null }))); setSuggestKind('know'); }
            return;
          }
        } catch (e) {}
      }
      if (signedIn && window.ShapeSearch) {
        try { const r = await window.ShapeSearch.people('', 8); if (!dead && Array.isArray(r) && r.length) { setSuggested(r); setSuggestKind('on'); return; } } catch (e) {}
      }
      if (!dead) { setSuggested(demoPeople.slice(0, 8)); setSuggestKind('on'); }
    })();
    return () => { dead = true; };
  }, []);

  // Live typeahead — debounced 250ms; demo cast is the signed-out / error fallback.
  React.useEffect(() => {
    const query = q.trim();
    if (!query) { setRows(null); setBusy(false); return; }
    setBusy(true);
    let dead = false;
    const id = setTimeout(() => {
      const needle = query.replace(/^@/, '').toLowerCase();
      const local = demoPeople.filter(p => p.name.toLowerCase().includes(needle));
      if (signedIn && window.ShapeSearch) {
        window.ShapeSearch.people(query).then(r => { if (dead) return; setRows(Array.isArray(r) && r.length ? r : local); setBusy(false); })
          .catch(() => { if (!dead) { setRows(local); setBusy(false); } });
      } else { setRows(local); setBusy(false); }
    }, 250);
    return () => { dead = true; clearTimeout(id); };
  }, [q]);

  // Beyond people — channels, Shape Kitchen recipes, workouts, and coach plans
  // also match the query (sections under the people results on the All filter).
  const [chAll, setChAll] = useStateBSC([]);
  const [plansAll, setPlansAll] = useStateBSC([]);
  const [viewRecipe, setViewRecipe] = useStateBSC(null);
  const [viewWorkout, setViewWorkout] = useStateBSC(null);
  React.useEffect(() => {
    let dead = false;
    if (signedIn && window.ShapeChannels?.list) {
      window.ShapeChannels.list().then(r => {
        const list = (r && r.data) || [];
        if (!dead) setChAll(list.map(c => ({ id: c.id, name: c.name, blurb: c.description || '', memberCount: c.memberCount || (Array.isArray(c.members) ? c.members.length : 0) })));
      }).catch(() => {});
    }
    if (window.ShapeMarketPlans?.list) {
      window.ShapeMarketPlans.list().then(r => { if (!dead && Array.isArray(r)) setPlansAll(r); }).catch(() => {});
    }
    return () => { dead = true; };
  }, []);
  const needle = q.trim().replace(/^[@#]/, '').toLowerCase();
  const recipesAll = React.useMemo(() => (Array.isArray(SHAPE_KITCHEN_RECIPES) ? SHAPE_KITCHEN_RECIPES : []), []);
  const workoutsAll = React.useMemo(() => Object.entries(BS_CLIENT_WORKOUTS || {}).map(([title, detail]) => ({ title, detail })), []);
  // Channels/Recipes have their own chips: with no query the chip browses the
  // full list; typing filters it. On All they appear as 4-row sections.
  const chMatch = needle ? chAll.filter(c => (c.name + ' ' + c.blurb).toLowerCase().includes(needle)) : chAll;
  const recMatch = needle ? recipesAll.filter(r => String(r.title || '').toLowerCase().includes(needle)) : recipesAll;
  const chHits = filter === 'channels' ? chMatch.slice(0, 24) : (filter === 'all' && needle ? chMatch.slice(0, 4) : []);
  const recHits = filter === 'recipes' ? recMatch.slice(0, 24) : (filter === 'all' && needle ? recMatch.slice(0, 4) : []);
  const wkHits = (filter === 'all' && needle) ? workoutsAll.filter(w => (w.title + ' ' + ((w.detail && w.detail.meta) || '')).toLowerCase().includes(needle)).slice(0, 4) : [];
  const planHits = (filter === 'all' && needle) ? plansAll.filter(p => (p.name + ' ' + (p.meta || '') + ' ' + (p.coachName || '')).toLowerCase().includes(needle)).slice(0, 4) : [];
  // Nora (Shape's concierge) is staff, not a profiles row — searchable anyway.
  const noraHit = filter === 'all' && !!needle && ('nora'.includes(needle) || ['concierge', 'support', 'help', 'assistant'].some(w => w.startsWith(needle)));

  const isCoachRole = (r) => r === 'trainer' || r === 'nutritionist';
  const matchesFilter = (p) => filter === 'all' ? true : filter === 'coaches' ? isCoachRole(p.role) : filter === 'members' ? !isCoachRole(p.role) : false;
  const open = (p) => {
    // (Recents are recorded centrally when the profile mounts — covers profiles
    // viewed from anywhere, not just searched ones.)
    const kind = p.role === 'trainer' ? 'TRAINER' : p.role === 'nutritionist' ? 'NUTRI' : 'CLIENT';
    setViewPerson({ who: p.name, kind, userId: p.userId || undefined, init: bsInitials(p.name), photo: p.avatar || undefined, tier: p.points != null ? bsTierForPoints(p.points) : undefined, public: true });
  };
  React.useEffect(() => {
    const sync = () => setRecents(bsRecentSearchRead());
    window.addEventListener('shape:recentSearch', sync);
    return () => window.removeEventListener('shape:recentSearch', sync);
  }, []);

  if (viewPerson) return (
    <div style={{ position: 'absolute', inset: 0, zIndex: 230, background: t.PAPER }}>
      <BSPublicProfile person={viewPerson} onBack={() => setViewPerson(null)} />
    </div>
  );
  if (viewRecipe) return (
    <div style={{ position: 'absolute', inset: 0, zIndex: 230, background: t.PAPER }}>
      <BSShapeKitchenRecipe recipe={viewRecipe} onBack={() => setViewRecipe(null)} onAddGrocery={() => {}} groceryAdded={false} />
    </div>
  );
  if (viewWorkout) return (
    <div style={{ position: 'absolute', inset: 0, zIndex: 230, background: t.PAPER }}>
      <BSHomeWorkoutPreview workout={viewWorkout} onBack={() => setViewWorkout(null)} onStart={() => { onClose(); try { window.dispatchEvent(new Event('shape:startWorkout')); } catch (e) {} }} />
    </div>
  );

  const roleLabel = (r) => r === 'trainer' ? 'Trainer' : r === 'nutritionist' ? 'Nutritionist' : 'Member';
  const roleColor = (r) => r === 'trainer' ? '#c0533b' : r === 'nutritionist' ? '#a07a2e' : teal;
  const eyebrow = { fontFamily: t.MONO, fontSize: 8.5, fontWeight: 800, letterSpacing: '0.18em', textTransform: 'uppercase', color: t.INK50 };
  const meId = (typeof window !== 'undefined' && window.ShapeAuth?.getCachedState?.()?.user?.id) || null;
  const Row = (p, i) => {
    const actionable = signedIn && p.userId && p.userId !== meId;
    const sub = p.mutuals > 0 ? `${p.mutuals} mutual` : (p.followsMe ? 'Follows you' : null);
    return (
      <div key={(p.userId || p.name) + ':' + i} style={{ display: 'flex', alignItems: 'center', gap: 8, borderTop: i === 0 ? 0 : `1px solid ${t.HAIR}` }}>
        <button onClick={() => open(p)} style={{ flex: 1, minWidth: 0, textAlign: 'left', cursor: 'pointer', background: 'transparent', border: 0, padding: '11px 2px', display: 'flex', alignItems: 'center', gap: 12 }}>
          <BSFacetAvatar size={38} c={bsTierColor(p.points != null ? bsTierForPoints(p.points) : (p.tier || bsPostTier({ who: p.name })))} initial={bsInitials(p.name)} name={p.name} photo={p.avatar || undefined} showRank={false} />
          <span style={{ minWidth: 0, flex: 1 }}>
            <span style={{ display: 'block', fontFamily: t.MONO, fontSize: 8, fontWeight: 800, letterSpacing: '0.16em', textTransform: 'uppercase', color: roleColor(p.role) }}>{roleLabel(p.role)}{sub ? <span style={{ color: t.INK50 }}> · {sub}</span> : null}</span>
            <span style={{ display: 'block', marginTop: 2, fontFamily: t.DISPLAY, fontSize: 16, fontWeight: 700, color: t.INK, letterSpacing: '-0.01em', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{p.name}</span>
          </span>
        </button>
        {actionable ? <BSSearchFollowBtn uid={p.userId} teal={teal} /> : null}
        {actionable ? <BSSearchMsgBtn uid={p.userId} name={p.name} /> : null}
        {!actionable ? <button onClick={() => open(p)} aria-label={`Open ${p.name}'s profile`} style={{ background: 'transparent', border: 0, padding: '0 2px', cursor: 'pointer', fontFamily: t.MONO, fontSize: 13, color: t.INK50 }}>›</button> : null}
      </div>
    );
  };

  // Non-people result row — mono glyph tile + title + sub (channels / recipes /
  // workouts / coach plans).
  const TileRow = ({ glyph, color, title, sub, onClick, first }) => (
    <div style={{ borderTop: first ? 0 : `1px solid ${t.HAIR}` }}>
      <button onClick={onClick} style={{ width: '100%', textAlign: 'left', cursor: 'pointer', background: 'transparent', border: 0, padding: '11px 2px', display: 'flex', alignItems: 'center', gap: 12 }}>
        <span style={{ width: 38, height: 38, flexShrink: 0, borderRadius: 11, border: `1px solid ${color}55`, background: `${color}14`, color, display: 'grid', placeItems: 'center', fontFamily: t.MONO, fontSize: 15, fontWeight: 800 }}>{glyph}</span>
        <span style={{ minWidth: 0, flex: 1 }}>
          <span style={{ display: 'block', fontFamily: t.DISPLAY, fontSize: 16, fontWeight: 700, color: t.INK, letterSpacing: '-0.01em', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{title}</span>
          <span style={{ display: 'block', marginTop: 2, fontFamily: t.MONO, fontSize: 8.5, letterSpacing: '0.08em', textTransform: 'uppercase', color: t.INK50, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{sub}</span>
        </span>
        <span style={{ fontFamily: t.MONO, fontSize: 13, color: t.INK50 }}>›</span>
      </button>
    </div>
  );

  const list = (rows || []).filter(matchesFilter);
  const sugg = suggested.filter(matchesFilter);
  const recs = recents.filter(matchesFilter);
  const moreHits = filter === 'all' ? (chHits.length + recHits.length + wkHits.length + planHits.length) : 0;

  return (
    <div style={{ position: 'absolute', inset: 0, zIndex: 230, background: t.PAPER, display: 'flex', flexDirection: 'column' }}>
      <div style={{ flex: '0 0 auto', padding: `46px ${t.padX}px 0` }}>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
            {BSLogo && <BSLogo size={16} color={t.INK} />}
            <div style={{ fontFamily: t.MONO, fontSize: 9, letterSpacing: '0.12em', textTransform: 'uppercase', color: t.INK70 }}>Vol. 1 · No. 1</div>
          </div>
          <button onClick={onClose} aria-label="Close search" style={{ background: 'transparent', border: 0, color: t.INK50, cursor: 'pointer', fontFamily: t.MONO, fontSize: 15, fontWeight: 800, padding: 4, lineHeight: 1 }}>✕</button>
        </div>
        <div style={{ marginTop: 14, fontFamily: t.DISPLAY, fontSize: 29, fontWeight: 700, letterSpacing: '-0.03em', color: t.INK, lineHeight: 1 }}>Search Shape<span style={{ color: teal }}>.</span></div>
        <input ref={inputRef} value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search names, @handles, goals…"
          style={{ width: '100%', boxSizing: 'border-box', marginTop: 12, padding: '10px 2px', border: 0, borderBottom: `1px solid ${t.RULE}`, borderRadius: 0, background: 'transparent', color: t.INK, fontFamily: t.DISPLAY, fontSize: 17, outline: 'none' }} />
        <div className="bs-hide-scroll" style={{ display: 'flex', gap: 7, padding: '12px 0 10px', overflowX: 'auto' }}>
          {[['all', 'All'], ['members', 'Members'], ['coaches', 'Coaches'], ['channels', 'Channels'], ['recipes', 'Recipes']].map(([k, label]) => (
            <button key={k} onClick={() => setFilter(k)} style={{ flexShrink: 0, padding: '6px 13px', borderRadius: 999, cursor: 'pointer', border: `1px solid ${filter === k ? teal : t.RULE}`, background: filter === k ? (t.isLight ? `${teal}14` : `${teal}22`) : 'transparent', color: filter === k ? teal : t.INK50, fontFamily: t.MONO, fontSize: 9.5, fontWeight: 700, letterSpacing: '0.1em', textTransform: 'uppercase' }}>{label}</button>
          ))}
        </div>
      </div>
      <div style={{ flex: 1, overflowY: 'auto', padding: `2px ${t.padX}px 40px` }}>
        {filter === 'channels' ? (
          chHits.length ? (
            <>
              <div style={{ ...eyebrow, padding: '8px 0 2px' }}>{chHits.length} {chHits.length === 1 ? 'channel' : 'channels'}</div>
              {chHits.map((c, i) => <TileRow key={'ch' + c.id} first={i === 0} glyph="#" color={teal} title={c.name} sub={`${c.memberCount || 0} member${c.memberCount === 1 ? '' : 's'}${c.blurb ? ' · ' + c.blurb : ''}`} onClick={() => { onClose(); try { window.dispatchEvent(new CustomEvent('shape:openConversation', { detail: { channel: c } })); } catch (e) {} }} />)}
            </>
          ) : (
            <div style={{ padding: '18px 0', fontFamily: t.DISPLAY, fontSize: 15, color: t.INK50 }}>{needle ? `No channels match “${q.trim()}”.` : (signedIn ? 'No channels yet — start one from Chat → Channels.' : 'Sign in to browse the community channels.')}</div>
          )
        ) : filter === 'recipes' ? (
          recHits.length ? (
            <>
              <div style={{ ...eyebrow, padding: '8px 0 2px' }}>{recHits.length} {recHits.length === 1 ? 'recipe' : 'recipes'} · Shape Kitchen</div>
              {recHits.map((r, i) => <TileRow key={'rc' + (r.id || r.title)} first={i === 0} glyph="◇" color={teal} title={r.title} sub={`${r.kcal ? r.kcal + ' kcal' : 'Recipe'}${r.macros && r.macros.p ? ' · ' + r.macros.p + 'P' : ''}${r.time ? ' · ' + r.time : ''}`} onClick={() => setViewRecipe(r)} />)}
            </>
          ) : (
            <div style={{ padding: '18px 0', fontFamily: t.DISPLAY, fontSize: 15, color: t.INK50 }}>No recipes match “{q.trim()}”.</div>
          )
        ) : q.trim() ? (
          busy && !rows ? (
            <div style={{ padding: '18px 0', ...eyebrow }}>Searching…</div>
          ) : (list.length === 0 && moreHits === 0 && !noraHit) ? (
            <div style={{ padding: '18px 0' }}>
              <div style={{ fontFamily: t.DISPLAY, fontSize: 15, color: t.INK50 }}>Nothing on Shape matches “{q.trim()}”.</div>
              <button onClick={() => { onClose(); try { window.dispatchEvent(new Event('shape:openMarket')); } catch (e) {} }} style={{ marginTop: 10, background: 'transparent', border: 0, padding: 0, cursor: 'pointer', fontFamily: t.MONO, fontSize: 9.5, fontWeight: 800, letterSpacing: '0.14em', textTransform: 'uppercase', color: teal }}>Browse coaches on the marketplace →</button>
            </div>
          ) : (
            <>
              {noraHit && (
                <>
                  <div style={{ ...eyebrow, padding: '8px 0 2px' }}>Shape staff</div>
                  <button onClick={() => { onClose(); try { window.dispatchEvent(new CustomEvent('shape:openConversation', { detail: { support: true, name: 'Nora' } })); } catch (e) {} }} style={{ width: '100%', textAlign: 'left', cursor: 'pointer', background: 'transparent', border: 0, padding: '11px 2px', display: 'flex', alignItems: 'center', gap: 12 }}>
                    <BSFacetAvatar size={38} c={'#2e6fa0'} initial="N" name="Nora" photo={BS_NORA_AVATAR} live showRank={false} />
                    <span style={{ minWidth: 0, flex: 1 }}>
                      <span style={{ display: 'block', fontFamily: t.MONO, fontSize: 8, fontWeight: 800, letterSpacing: '0.16em', textTransform: 'uppercase', color: teal }}>Shape's Concierge · always online</span>
                      <span style={{ display: 'block', marginTop: 2, fontFamily: t.DISPLAY, fontSize: 16, fontWeight: 700, color: t.INK, letterSpacing: '-0.01em' }}>Nora</span>
                    </span>
                    <span style={{ fontFamily: t.MONO, fontSize: 13, color: t.INK50 }}>›</span>
                  </button>
                </>
              )}
              {list.length > 0 && (
                <>
                  <div style={{ ...eyebrow, padding: '8px 0 2px' }}>{list.length} {list.length === 1 ? 'person' : 'people'}</div>
                  {list.map(Row)}
                </>
              )}
              {filter === 'all' && chHits.length > 0 && (
                <>
                  <div style={{ ...eyebrow, padding: '16px 0 2px' }}>Channels</div>
                  {chHits.map((c, i) => <TileRow key={'ch' + c.id} first={i === 0} glyph="#" color={teal} title={c.name} sub={`${c.memberCount || 0} member${c.memberCount === 1 ? '' : 's'}${c.blurb ? ' · ' + c.blurb : ''}`} onClick={() => { onClose(); try { window.dispatchEvent(new CustomEvent('shape:openConversation', { detail: { channel: c } })); } catch (e) {} }} />)}
                </>
              )}
              {filter === 'all' && recHits.length > 0 && (
                <>
                  <div style={{ ...eyebrow, padding: '16px 0 2px' }}>Recipes · Shape Kitchen</div>
                  {recHits.map((r, i) => <TileRow key={'rc' + (r.id || r.title)} first={i === 0} glyph="◇" color={teal} title={r.title} sub={`${r.kcal ? r.kcal + ' kcal' : 'Recipe'}${r.macros && r.macros.p ? ' · ' + r.macros.p + 'P' : ''}${r.time ? ' · ' + r.time : ''}`} onClick={() => setViewRecipe(r)} />)}
                </>
              )}
              {filter === 'all' && wkHits.length > 0 && (
                <>
                  <div style={{ ...eyebrow, padding: '16px 0 2px' }}>Workouts</div>
                  {wkHits.map((w, i) => <TileRow key={'wk' + w.title} first={i === 0} glyph="▣" color={t.RUST} title={w.title} sub={(w.detail && w.detail.meta) || 'Session'} onClick={() => setViewWorkout(w)} />)}
                </>
              )}
              {filter === 'all' && planHits.length > 0 && (
                <>
                  <div style={{ ...eyebrow, padding: '16px 0 2px' }}>Coach plans</div>
                  {planHits.map((p, i) => <TileRow key={'pl' + p.id} first={i === 0} glyph="✦" color={'#a07a2e'} title={p.name} sub={`${p.coachName}${p.price ? ' · ' + p.price : ''}`} onClick={() => setViewPerson({ who: p.coachName, kind: p.providerRole === 'nutritionist' ? 'NUTRI' : 'TRAINER', userId: p.ownerId || undefined, init: bsInitials(p.coachName), public: true })} />)}
                </>
              )}
            </>
          )
        ) : (
          <>
            {recs.length > 0 && (
              <>
                <div style={{ display: 'flex', alignItems: 'baseline', justifyContent: 'space-between', padding: '8px 0 2px' }}>
                  <span style={eyebrow}>Recent</span>
                  <button onClick={() => { try { localStorage.removeItem(BS_RECENT_SEARCH_KEY); } catch (e) {} setRecents([]); }} style={{ background: 'transparent', border: 0, padding: 0, cursor: 'pointer', fontFamily: t.MONO, fontSize: 8.5, fontWeight: 800, letterSpacing: '0.14em', textTransform: 'uppercase', color: teal }}>Clear</button>
                </div>
                {recs.map(Row)}
              </>
            )}
            {sugg.length > 0 && (
              <>
                <div style={{ ...eyebrow, padding: `${recs.length ? 18 : 8}px 0 2px` }}>{suggestKind === 'know' ? 'People you may know' : 'On Shape'}</div>
                {sugg.map(Row)}
              </>
            )}
            {!signedIn && <div style={{ marginTop: 16, fontFamily: t.MONO, fontSize: 8.5, letterSpacing: '0.1em', textTransform: 'uppercase', color: t.INK50 }}>Preview · sign in to search every real account</div>}
          </>
        )}
      </div>
    </div>
  );
}

// Nora's avatar image — drop `nora-avatar.png` into mobile-app/public and it
// lights up everywhere (BSFacetAvatar falls back to the "N" initial until then).
const BS_NORA_AVATAR = `${import.meta.env.BASE_URL}nora-avatar.png`;

// ── Nora's profile — Shape's AI assistant ─────────────────────────────────────
// A lightweight STAFF profile (deliberately not a member Terrain profile — no
// score/followers/climb): who she is, always-online status, what she helps
// with, and the human-escalation promise. Opened by tapping her avatar/name in
// the Support thread.
function BSNoraProfile({ onClose }) {
  const t = useBS();
  const BLUE = '#2e6fa0', TEAL = t.isLight ? '#0a8f87' : '#34d6c5';
  const MONO = t.MONO, SERIF = t.DISPLAY;
  const helps = [
    ['Connecting integrations', 'Whoop, Oura, Strava, Spotify & more'],
    ['Your plan & programs', 'Workouts, meals, schedules, swaps'],
    ['Billing & membership', 'The $5/mo plan, coach payments, receipts'],
    ['Account & settings', 'Profile, privacy, notifications, data'],
    ['Finding a coach', 'Matching you with vetted trainers & RDs'],
  ];
  const sheet = (
    <div className="bs-scroll" style={{ position: 'absolute', inset: 0, zIndex: 100000, background: t.PAPER_BG, color: t.INK, overflowY: 'auto' }}>
      <div style={{ padding: `46px ${t.padX}px calc(28px + env(safe-area-inset-bottom, 0px))` }}>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <button onClick={onClose} style={{ background: bsTHexA(t.INK, 0.06), border: `1px solid ${bsTHexA(t.INK, 0.18)}`, color: t.INK, borderRadius: 999, padding: '5px 11px', cursor: 'pointer', fontFamily: MONO, fontSize: 9, letterSpacing: '0.14em', textTransform: 'uppercase' }}>← Back</button>
          <span style={{ fontFamily: MONO, fontSize: 8.5, letterSpacing: '0.16em', textTransform: 'uppercase', color: bsTHexA(t.INK, 0.45) }}>Shape team</span>
        </div>
        {/* identity — the live ring + dot overflow the avatar box, so pad the
            wrapper to keep clear air before the eyebrow */}
        <div style={{ textAlign: 'center', marginTop: 26 }}>
          <div style={{ display: 'inline-block', padding: '6px 6px 14px' }}>
            <BSFacetAvatar size={96} c={BLUE} initial="N" name="Nora" photo={BS_NORA_AVATAR} showRank={false} live BG={t.PAPER_BG} INK={t.INK} />
          </div>
          <div style={{ marginTop: 10, fontFamily: MONO, fontSize: 9, fontWeight: 700, letterSpacing: '0.2em', textTransform: 'uppercase', color: TEAL }}>Always online</div>
          <h1 style={{ fontFamily: SERIF, fontSize: 38, fontWeight: t.W.display, letterSpacing: '-0.03em', margin: '8px 0 0', lineHeight: 1 }}>Nora<span style={{ color: TEAL }}>.</span></h1>
          <div style={{ marginTop: 10, fontFamily: SERIF, fontSize: 15, fontStyle: 'italic', color: bsTHexA(t.INK, 0.65), lineHeight: 1.5, padding: '0 14px' }}>Shape's AI concierge — here for every member and visitor, day and night.</div>
        </div>
        {/* stats */}
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: 8, marginTop: 20 }}>
          {[['Instant', 'Replies'], ['24/7', 'Hours'], ['Human', 'Backup']].map(([v, l]) => (
            <div key={l} style={{ textAlign: 'center', borderRadius: 14, border: `1px solid ${bsTHexA(t.INK, 0.12)}`, background: bsTHexA(t.INK, 0.04), padding: '12px 6px' }}>
              <div style={{ fontFamily: SERIF, fontSize: 17, fontWeight: 700, letterSpacing: '-0.02em', color: t.INK }}>{v}</div>
              <div style={{ marginTop: 3, fontFamily: MONO, fontSize: 7.5, letterSpacing: '0.14em', textTransform: 'uppercase', color: bsTHexA(t.INK, 0.5) }}>{l}</div>
            </div>
          ))}
        </div>
        {/* what she helps with */}
        <div style={{ marginTop: 22 }}>
          <div style={{ fontFamily: MONO, fontSize: 9, fontWeight: 800, letterSpacing: '0.18em', textTransform: 'uppercase', color: BLUE, paddingBottom: 6 }}>What Nora helps with</div>
          {helps.map(([title, sub], i) => (
            <div key={title} style={{ padding: '10px 2px', borderTop: i ? `1px solid ${bsTHexA(t.INK, 0.08)}` : 0 }}>
              <div style={{ fontFamily: SERIF, fontSize: 15, fontWeight: 600, color: t.INK, letterSpacing: '-0.01em' }}>{title}</div>
              <div style={{ marginTop: 2, fontFamily: MONO, fontSize: 8.5, letterSpacing: '0.06em', textTransform: 'uppercase', color: bsTHexA(t.INK, 0.5) }}>{sub}</div>
            </div>
          ))}
        </div>
        {/* escalation note */}
        <div style={{ marginTop: 16, borderRadius: 14, border: `1px solid ${bsTHexA(BLUE, 0.35)}`, background: bsTHexA(BLUE, 0.08), padding: '12px 14px', fontFamily: SERIF, fontSize: 13.5, fontStyle: 'italic', color: bsTHexA(t.INK, 0.75), lineHeight: 1.5 }}>
          “If I can't sort it out, I bring in the human Shape team — you never get stuck with a bot.”
        </div>
        <button onClick={onClose} style={{ marginTop: 18, width: '100%', minHeight: 46, borderRadius: 999, background: TEAL, color: '#06110e', border: 0, cursor: 'pointer', fontFamily: MONO, fontSize: 10.5, letterSpacing: '0.14em', textTransform: 'uppercase', fontWeight: 800 }}>Message Nora →</button>
      </div>
    </div>
  );
  const surface = (typeof document !== 'undefined' && document.getElementById('bs-phone-surface')) || (typeof document !== 'undefined' ? document.body : null);
  return surface ? createPortal(sheet, surface) : sheet;
}

// Feed action glyphs — crisp geometric inline SVGs (replace the typographic
// ↑ ↳ ↗ ✉ ⇄ for a less-analog, instrument look). Monochrome, square caps, and
// `currentColor` stroke so each inherits its pill's tint (tier when active,
// muted otherwise). One helper, sized per call.
function bsFeedIcon(name, size = 12, solid = false) {
  const p = { width: size, height: size, viewBox: '0 0 16 16', fill: 'none', stroke: 'currentColor', strokeWidth: 1.7, strokeLinecap: 'square', strokeLinejoin: 'miter', 'aria-hidden': true, style: { display: 'block', flexShrink: 0 } };
  switch (name) {
    case 'react':   // boost — sharp upward arrow
      return <svg {...p}><path d="M8 13.5V3.5" /><path d="M3.8 7.7L8 3.5l4.2 4.2" /></svg>;
    case 'heart':   // like — geometric heart (filled when liked)
      return <svg {...p} fill={solid ? 'currentColor' : 'none'} strokeLinejoin="round"><path d="M8 13.3 2.9 8.2A3 3 0 0 1 8 4.9 3 3 0 0 1 13.1 8.2Z" /></svg>;
    case 'comment': // squared speech plate w/ tail
      return <svg {...p}><path d="M2.3 3.2h11.4v7H6.4L3.8 12.6V10.2H2.3z" /></svg>;
    case 'share':   // 3-node share graph
      return <svg {...p}><circle cx="12" cy="3.4" r="1.7" /><circle cx="4" cy="8" r="1.7" /><circle cx="12" cy="12.6" r="1.7" /><path d="M10.5 4.3 5.5 7.1M5.5 8.9l5 2.8" /></svg>;
    case 'send':    // paper plane
      return <svg {...p}><path d="M14.5 1.8 1.6 7.2l4.8 1.7 1.7 4.9z" /><path d="M14.5 1.8 6.4 8.9" /></svg>;
    case 'repost':  // opposed cycle arrows
      return <svg {...p}><path d="M2.8 5.6H11M9 3.6 11 5.6 9 7.6" /><path d="M13.2 10.4H5M7 8.4 5 10.4 7 12.4" /></svg>;
    default: return null;
  }
}

// One modern comment row — facet avatar + a name/text column so every comment
// lines up evenly (fixed avatar gutter), shared by the card preview and the
// full-screen detail page. `who === 'You'` reads in the accent.
function BSFeedComment({ c, t, cardInk, muted, feedAvatars = {}, real = false, size = 26 }) {
  const nm = c.who || 'Member';
  const isMe = nm === 'You';
  const photo = isMe ? (bsMyPhoto() || undefined) : (c.userId ? feedAvatars[c.userId] : (real ? undefined : bsDemoFace(nm)));
  const col = isMe ? bsMyTierColor() : bsTierColor(bsPostTier({ who: nm }));
  const init = isMe ? bsMyInitials() : bsInitials(nm);
  const meC = t.isLight ? '#0a8f87' : '#34d6c5';
  return (
    <div style={{ display: 'flex', gap: 9, marginBottom: 12, alignItems: 'flex-start' }}>
      <BSFacetAvatar size={size} c={col} initial={init} name={nm} photo={photo} showRank={false} />
      <div style={{ flex: 1, minWidth: 0, paddingTop: 1 }}>
        <div style={{ fontFamily: t.MONO, fontSize: 8.5, fontWeight: 800, letterSpacing: '0.1em', textTransform: 'uppercase', color: isMe ? meC : muted }}>{String(nm).split(' ')[0]}</div>
        <div style={{ fontFamily: t.BODY, fontSize: 13.5, color: cardInk, lineHeight: 1.42, marginTop: 3 }}>{c.text || c.body}</div>
      </div>
    </div>
  );
}

