              const vals = d.trace, lo = Math.min(...vals), hi = Math.max(...vals), W = 100, H = 36, rng = (hi - lo) || 1;
              const pts = vals.map((v, i) => [(i / (vals.length - 1)) * W, H - ((v - lo) / rng) * (H - 5) - 2.5]);
              const line = pts.map((p, i) => `${i ? 'L' : 'M'}${p[0].toFixed(1)} ${p[1].toFixed(1)}`).join(' ');
